79:     /** Initialize the ModelBuilder, validating all arguments and preparing the
80:      *  training frame.  This call is expected to be overridden in the subclasses
81:      *  and each subclass will start with "super.init();".  This call is made
82:      *  by the front-end whenever the GUI is clicked, and needs to be fast;
83:      *  heavy-weight prep needs to wait for the trainModel() call.
84:      */
85:     @Override public void init(boolean expensive) {
86:         super.init(expensive);
87:         // Initialize local variables
88:         if( _parms._mtries < 1 && _parms._mtries != -1 && _parms._mtries != -2 )
89:             error("_mtries", "mtries must be -1 (converted to sqrt(features)) or -2 (All features) or >= 1 but it is " + _parms._mtries);
90:         if( _train != null ) {
91:             int ncols = _train.numCols();
92:             if( _parms._mtries != -1 && _parms._mtries != -2 && !(1 <= _parms._mtries && _parms._mtries < ncols /*ncols includes the response*/))
93:                 error("_mtries","Computed mtries should be -1 or -2 or in interval [1,"+ncols+"[ but it is " + _parms._mtries);
94:         }
95:         if (_parms._sample_rate == 1f && _valid == null)
96:             warn("_sample_rate", "Sample rate is 100% and no validation dataset. There are no out-of-bag data to compute error estimates on the training data!");
97:         if (hasOffsetCol())
98:             error("_offset_column", "Offsets are not yet supported for Uplift DRF.");
99:         if (hasWeightCol())
100:             error("_weight_column", "Weights are not yet supported for Uplift DRF.");
101:         if (hasFoldCol())
102:             error("_fold_column", "Cross-validation is not yet supported for Uplift DRF.");
103:         if (_parms._nfolds > 0)
104:             error("_nfolds", "Cross-validation is not yet supported for Uplift DRF.");
105:         if (_nclass == 1)
106:             error("_distribution", "UpliftDRF currently support binomial classification problems only.");
107:         if (_nclass > 2 || _parms._distribution.equals(DistributionFamily.multinomial)) 
108:             error("_distribution", "UpliftDRF currently does not support multinomial distribution.");
109:         if (_parms._treatment_column == null) 
110:             error("_treatment_column", "The treatment column has to be defined.");
111:         if (_parms._custom_distribution_func != null)
112:             error("_custom_distribution_func", "The custom distribution is not yet supported for Uplift DRF.");
113:     }

200:             for( ; depth<_parms._max_depth; depth++ ) {
201:                 hcs = buildLayer(_train, _parms._nbins, ktrees[0], leafs, hcs, _parms._build_tree_one_node);
202:                 
203:                 // If we did not make any new splits, then the tree is split-to-death
204:                 if( hcs == null ) break;
205:             }
206:             // Each tree bottomed-out in a DecidedNode; go 1 more level and insert
207:             // LeafNodes to hold predictions.
208:             DTree treeTr = ktrees[0];
209:             ktrees[1] = new DTree(ktrees[0]); // make a deep copy of the tree to assign control prediction to the leaves
210:             DTree treeCt = ktrees[1]; 
211:             int leaf = leafs[0] = treeTr.len();
212:             for (int nid = 0; nid < leaf; nid++) {
213:                 if (treeTr.node(nid) instanceof DTree.DecidedNode) { // Should be the same for treatment and control tree
214:                     DTree.DecidedNode dnTr = treeTr.decided(nid); // Treatment tree node
215:                     DTree.DecidedNode dnCt = treeCt.decided(nid); // Control tree node
216:                     if (dnTr._split == null) { // No decision here, no row should have this NID now
217:                         if (nid == 0) { // Handle the trivial non-splitting tree
218:                             DTree.LeafNode lnTr = new DTree.LeafNode(treeTr, -1, 0);
219:                             lnTr._pred = (float) (_model._output._priorClassDist[1]);
220:                             DTree.LeafNode lnCt = new DTree.LeafNode(treeCt, -1, 0);
221:                             lnCt._pred = (float) (_model._output._priorClassDist[0]);
222:                         }
223:                         continue;
224:                     }
225:                     for (int i = 0; i < dnTr._nids.length; i++) {
226:                         int cnid = dnTr._nids[i];
227:                         if (cnid == -1 || // Bottomed out (predictors or responses known constant)
228:                                 treeTr.node(cnid) instanceof DTree.UndecidedNode || // Or chopped off for depth
229:                                 (treeTr.node(cnid) instanceof DTree.DecidedNode &&  // Or not possible to split
230:                                         ((DTree.DecidedNode) treeTr.node(cnid))._split == null)) {
231:                             DTree.LeafNode lnTr = new DTree.LeafNode(treeTr, nid);
232:                             lnTr._pred = (float) dnTr.predTreatment(i);  // Set prediction into the treatment leaf
233:                             dnTr._nids[i] = lnTr.nid(); // Mark a leaf here for treatment 
234:                             DTree.LeafNode lnCt = new DTree.LeafNode(treeCt, nid);
235:                             lnCt._pred = (float) dnCt.predControl(i);  // Set prediction into the control leaf
236:                             dnCt._nids[i] = lnCt.nid(); // Mark a leaf here for control
237:                         }
238:                     }
239:                 } 
240:             }
241:         }
