71:     @Override public boolean binomialOpt() { return false; }
72:     
73:     /** Bulk scoring API for one row.  Chunks are all compatible with the model,
74:      *  and expect the last Chunks are for the final distribution and prediction.
75:      *  Default method is to just load the data into the tmp array, then call
76:      *  subclass scoring logic. */
77:     @Override protected double[] score0(double[] data, double[] preds, double offset, int ntrees) {
78:         super.score0(data, preds, offset, ntrees);
79:         int N = _output._ntrees;
80:         preds[1] /= N;
81:         preds[2] /= N;
82:         preds[0] = preds[1] - preds[2];
83:         return preds;
84:     }
