1: package hex.tree.uplift;
2: 
3: import static water.util.MathUtils.log2;
4: 
5: public class KLDivergence extends Divergence {
6:     
7:     @Override
8:     public double metric(double prCT1, double prCT0) {
9:         return prCT1 * log2(prCT1 / prCT0 == 0 ? ZERO_TO_DIVIDE : prCT0);
10:     }
11:     
12:     @Override
13:     public double norm(
14:         double prCT1, double prCT0, 
15:         double prLCT1, double prLCT0
16:     ) {
17:         double klCT = node(prCT1, prCT0);
18:         double entCT =  -(prCT1 * log2(prCT1) + prCT0 * log2(prCT0));
19:         double entCT1 = -(prLCT1 * log2(prLCT1) + (1 - prLCT1) * log2((1 - prLCT1)));
20:         double entCT0 = -(prLCT0 * log2(prLCT0) + (1 - prLCT0) * log2((1 - prLCT0)));
21:         return klCT * entCT + prCT1 * entCT1 + prCT0 * entCT0 + 0.5;
22:     }
23:     
24: }

1: package hex.tree.uplift;
2: 
3: public class EuclideanDistance extends Divergence {
4: 
5:     @Override
6:     public double metric(double prCT1, double prCT0) {
7:         return (prCT1 - prCT0) * (prCT1 - prCT0);
8:     }
9: 
10:     @Override
11:     public double norm(
12:         double prCT1, double prCT0,
13:         double prLCT1, double prLCT0
14:     ) {
15:         double nodeCT = node(prLCT1, prLCT0);
16:         double giniCT = 2 * prCT1 * (1 - prCT1);
17:         double giniCT1 = 2 * prLCT1 * (1 - prLCT1);
18:         double giniCT0 = 2 * prLCT0 * (1 - prLCT0);
19:         return giniCT * nodeCT + giniCT1 * prCT1 + giniCT0 * prCT0 + 0.5;
20:     }
21: }

1: package hex.tree.uplift;
2: 
3: public class ChiSquaredDivergence extends EuclideanDistance {
4: 
5:     @Override
6:     public double metric(double prCT1, double prCT0) {
7:         return ((prCT1 - prCT0) * (prCT1 - prCT0)) / (prCT0 == 0 ? Divergence.ZERO_TO_DIVIDE : prCT0);
8:     }
9: 
10: }

