356:     /**
357:      * Builder to process input data to build histogram in parallel. This builder is used to calculate AUUC quickly.
358:      */
359:     public static class AUUCBuilder extends Iced {
360:         final int _nBins;
361:         final double[]_thresholds;      // thresholds
362:         final long[] _treatment;        // number of data from treatment group
363:         final long[] _control;          // number of data from control group
364:         final long[] _yTreatment;       // number of data from treatment group with prediction = 1 
365:         final long[] _yControl;         // number of data from control group with prediction = 1 
366:         final long[] _frequency;        // frequency of data in each bin
367:         long _n;
368:         
369:         public AUUCBuilder(double[] thresholds) {
370:             int nBins = thresholds.length;
371:             _nBins = nBins;
372:             _thresholds = thresholds;      
373:             _treatment = new long[nBins];  
374:             _control = new long[nBins];   
375:             _yTreatment = new long[nBins]; 
376:             _yControl = new long[nBins];  
377:             _frequency = new long[nBins];
378:         }
379: 
380:         public void perRow(double pred, double w, double y, float treatment) {
381:             if (w == 0) {return;}
382:             for(int t = 0; t < _thresholds.length; t++) {
383:                 if (pred >= _thresholds[t] && (t == 0 || pred <_thresholds[t-1])) {
384:                     _n++;
385:                     _frequency[t]++;
386:                     if(treatment == 1){
387:                         _treatment[t]++;
388:                         if(y == 1){ 
389:                             _yTreatment[t]++;
390:                         }
391:                     } else {
392:                         _control[t]++;
393:                         if(y == 1){
394:                             _yControl[t]++;
395:                         }
396:                     }
397:                     break;
398:                 }
399:             }
400:         }

425:     /** AUUC type enum
426:      *
427:      *  This is an Enum class, with an exec() function to compute the criteria
428:      *  from the basic parts, and from an AUUC at a given threshold index.
429:      */
430:     public enum AUUCType {
431:         AUTO() { 
432:             @Override 
433:             double exec(long treatment, long control, long yTreatment, long yControl) {
434:                 return qini.exec(treatment, control, yTreatment, yControl);
435:             }
436:         },
437:         qini() { 
438:             @Override 
439:             double exec(long treatment, long control, long yTreatment, long yControl) {
440:                 double norm = treatment / (double)control;
441:                 return yTreatment - yControl * norm;
442:             }
443:         },
444:         lift() {
445:             @Override 
446:             double exec(long treatment, long control, long yTreatment, long yControl) {
447:                 return yTreatment / (double) treatment - yControl / (double)control;
448:             }
449:         },
450:         gain() {
451:             @Override 
452:             double exec(long treatment, long control, long yTreatment, long yControl) {
453:                 return lift.exec(treatment, control, yTreatment, yControl) * (double)(treatment + control);}
454:         };
455:         
456:         /** @param treatment
457:          *  @param control
458:          *  @param yTreatment
459:          *  @param yControl
460:          *  @return metric value */
461:         abstract double exec(long treatment, long control, long yTreatment, long yControl );
462:         public double exec(AUUC auc, int idx) { return exec(auc.treatment(idx),auc.control(idx),auc.yTreatment(idx),auc.yControl(idx)); }
463: 
464:         public static final AUUCType[] VALUES = values();
465: 
466:         public static final AUUCType[] VALUES_WITHOUT_AUTO = ArrayUtils.remove(values().clone(), ArrayUtils.find(AUUCType.values(), AUTO));
467: 
468:         public static String nameAuto(){
469:             return qini.name();
470:         }
471: 
472:         /** Convert a criterion into a threshold index that maximizes the criterion
473:          *  @return Threshold index that maximizes the criterion
474:          */
475:         public int maxCriterionIdx(AUUC auuc) {
476:             double md = -Double.MAX_VALUE;
477:             int mx = -1;
478:             for( int i=0; i<auuc._nBins; i++) {
479:                 double d = exec(auuc,i);
480:                 if( d > md ) {
481:                     md = d;
482:                     mx = i;
483:                 }
484:             }
485:             return mx;
486:         }
487:     }

