166:     public LinkedList<Double> getTotalEffects(Node x, Node y) {
167:         List<Node> parents = this.cpdag.getParents(x);
168:         List<Node> children = this.cpdag.getChildren(x);
169: 
170:         List<Node> siblings = new ArrayList<>(this.cpdag.getAdjacentNodes(x));
171:         siblings.removeAll(parents);
172:         siblings.removeAll(children);
173: 
174:         int size = siblings.size();
175:         SublistGenerator gen = new SublistGenerator(size, size);
176:         int[] choice;
177: 
178:         LinkedList<Double> totalEffects = new LinkedList<>();
179: 
180:         while ((choice = gen.next()) != null) {
181:             try {
182:                 List<Node> siblingsChoice = GraphUtils.asList(choice, siblings);
183: 
184:                 if (!isLegalParentSet(parents, siblingsChoice)) {
185:                     continue;
186:                 }
187: 
188:                 double beta;
189: 
190:                 if (idaType == IDA_TYPE.REGULAR) {
191:                     beta = getRegularIdaBeta(x, y, parents, siblingsChoice);
192:                 } else {
193:                     beta = getOptimalIdaBeta(x, y, siblings, siblingsChoice);
194:                 }
195: 
196:                 totalEffects.add(beta);
197:             } catch (Exception e) {
198:                 TetradLogger.getInstance().log(e.getMessage());
199:             }
200:         }
201: 
202:         Collections.sort(totalEffects);
203:         return totalEffects;
204:     }
