206:     private boolean isLegalParentSet(List<Node> parents, List<Node> siblingsChoice) {
207:         // Per Maathuis et al. (2009): orienting the chosen siblings S into X (and the
208:         // remaining siblings out of X) is locally valid iff it creates no NEW unshielded
209:         // collider at X. A collider s1 -> X <- s2 is unshielded only when s1 and s2 are
210:         // NOT adjacent, so (1) any two chosen siblings must be adjacent to each other,
211:         // and (2) each chosen sibling must be adjacent to every existing parent of X
212:         // (the parent edge is already oriented, so a non-adjacent pair would form a new
213:         // unshielded collider). Existing parents need not be mutually adjacent: any
214:         // collider among them is already present in the CPDAG.
215:         if (siblingsChoice.size() > 1) {
216:             ChoiceGenerator gen2 = new ChoiceGenerator(siblingsChoice.size(), 2);
217:             int[] choice2;
218: 
219:             while ((choice2 = gen2.next()) != null) {
220:                 List<Node> adj = GraphUtils.asList(choice2, siblingsChoice);
221:                 if (!this.cpdag.isAdjacentTo(adj.get(0), adj.get(1))) return false;
222:             }
223:         }
224: 
225:         for (Node sibling : siblingsChoice) {
226:             for (Node parent : parents) {
227:                 if (!this.cpdag.isAdjacentTo(sibling, parent)) return false;
228:             }
229:         }
230: 
231:         return true;
232:     }
