234:     private double getRegularIdaBeta(Node x, Node y, List<Node> parents, List<Node> siblingsChoice) {
235:         // Use LinkedHashSet to preserve insertion order so x remains first.
236:         Set<Node> _regressors = new LinkedHashSet<>();
237:         _regressors.add(x);
238:         _regressors.addAll(parents);
239:         _regressors.addAll(siblingsChoice);
240:         List<Node> regressors = new ArrayList<>(_regressors);
241: 
242:         TetradLogger.getInstance().log(x + " to " + y + " regressors (REGULAR IDA): " + regressors);
243: 
244:         if (regressors.contains(y)) {
245:             return 0.0;
246:         } else {
247:             return getBeta(regressors, x, y);

279:         try {
280:             if (dag) {
281:                 oSet = OSet.oSetDag(gPrime, x, y);
282:             } else {
283:                 oSet = OSet.oSetCpdag(gPrime, x, y, maxLengthAdjustment);
284:             }
285:         } catch (Exception e) {
286:             // If O-set computation fails, treat this orientation as yielding no effect
287:             TetradLogger.getInstance().warn("O-set computation failed for " + x + " ~~> " + y + ": " + e);
288:             return 0.0;
289:         }
290: 
291:         // If the O-set is null, this DAG is not O-set-eligible for (x,y), which must mean this
292:         // is not a legal CPDAG. That is, we took a CPDAG, oriented the undirected edges about
293:         // X, and applied the Meek rules, so all possibly oriented edges from X to Y are out of
294:         // X, which means the O-Set is defined. Then it's just a matter of whether there are any
295:         // such paths at all; if not, the total effect is zero for this orientation.
296:         if (oSet == null) {
297:             if (!gPrime.paths().isGraphAmenable(x, y, "PDAG", -1, Set.of())) {
298:                 throw new IllegalArgumentException("PDAG is weirdly not amenable for " + x + " ~~> " + y
299:                         + "; that must not have been a legal CPDAG.");
300:             } else {
301: 
302:                 // In this case it's amenable, but there are no amenable paths from X to Y, so the
303:                 // total effect is zero.
304:                 return 0.0;
305:             }
306:         }
307: 
308:         // O-set is defined, even if empty; estimate effect by regressing on X ∪ oSet
309:         Set<Node> regressorsSet = new LinkedHashSet<>();
310:         regressorsSet.add(x);
311:         regressorsSet.addAll(oSet);
312: 
313:         // Super-paranoid safety check: make sure Y is not in the regressor set
314:         regressorsSet.remove(y);
315: 
316:         List<Node> regressors = new ArrayList<>(regressorsSet);
317: 
318:         TetradLogger.getInstance().log(x + " to " + y + " regressors (OPTIMAL IDA): " + regressors
319:                 + "   O-set=" + oSet);
320: 
321:         return getBeta(regressors, x, y);

332:     public LinkedList<Double> getAbsTotalEffects(Node x, Node y) {
333:         LinkedList<Double> totalEffects = getTotalEffects(x, y);
334:         LinkedList<Double> absTotalEffects = new LinkedList<>();
335:         for (double d : totalEffects) {
