343:     /**
344:      * Returns a map from nodes in V \ {Y} to their minimum effects.
345:      *
346:      * @param y The child variable
347:      * @return Thia map.
348:      */
349:     public Map<Node, Double> calculateMinimumTotalEffectsOnY(Node y) {
350:         SortedMap<Node, Double> minEffects = new TreeMap<>();
351: 
352:         for (Node x : this.possibleCauses) {
353:             if (!(this.cpdag.containsNode(x) && this.cpdag.containsNode(y))) continue;
354:             LinkedList<Double> effects = getTotalEffects(x, y);
355:             if (!effects.isEmpty()) {
356:                 minEffects.put(x, effects.getFirst());
357:             }
358:         }
359: 
360:         return minEffects;
361:     }
