363:     /**
364:      * Returns a map from nodes in V \ {Y} to their minimum absolute effects on Y. This is the magnitude score CStaR
365:      * requires (Stekhoven et al. 2012): the absolute value is taken for each possible total effect first, and the
366:      * minimum of those absolute values is returned. (Taking the absolute value of the signed minimum instead would be
367:      * incorrect: effects -2 and -0.5 must yield 0.5, not 2.)
368:      *
369:      * @param y The child variable.
370:      * @return This map.
371:      */
372:     public Map<Node, Double> calculateMinimumAbsoluteTotalEffectsOnY(Node y) {
373:         SortedMap<Node, Double> minEffects = new TreeMap<>();
374: 
375:         for (Node x : this.possibleCauses) {
376:             if (!(this.cpdag.containsNode(x) && this.cpdag.containsNode(y))) continue;
377:             LinkedList<Double> effects = getAbsTotalEffects(x, y);
378:             if (!effects.isEmpty()) {
379:                 double min = effects.getFirst();
380: 
381:                 if (!Double.isFinite(min)) {
382:                     throw new IllegalStateException("Non-finite minimum absolute total effect for "
383:                             + x + " ~~> " + y + ": " + min);
384:                 }
385: 
386:                 minEffects.put(x, min);
387:             }
388:         }
389: 
390:         return minEffects;
391:     }

404:     private double getBeta(List<Node> regressors, Node parent, Node child) {
405:         if (!regressors.contains(parent)) {
406:             throw new IllegalArgumentException("The regressors must contain the parent node.");
407:         }
408: 
409:         try {
410:             // Build indices from covariance matrix variable ordering, not graph node ordering.
411:             List<Node> covVars = this.allCovariances.getVariables();
412:             Map<String, Integer> covIndices = new HashMap<>();
413:             for (int i = 0; i < covVars.size(); i++) {
414:                 covIndices.put(covVars.get(i).getName(), i);
415:             }
416: 
417:             // Position of parent in regressors list -- indexes into bStar.
418:             int parentIndexInRegressors = regressors.indexOf(parent);
419: 
420:             // Index of child in the covariance matrix.
421:             Integer yIndex = covIndices.get(child.getName());
422:             if (yIndex == null) {
423:                 throw new IllegalArgumentException("Child node not found in covariance matrix: "
424:                         + child.getName());
425:             }
426: 
427:             // Indices of regressors in the covariance matrix.
428:             int[] xIndices = new int[regressors.size()];
429:             for (int i = 0; i < regressors.size(); i++) {
430:                 Integer idx = covIndices.get(regressors.get(i).getName());
431:                 if (idx == null) {
432:                     throw new IllegalArgumentException("Regressor not found in covariance matrix: "
433:                             + regressors.get(i).getName());
434:                 }
435:                 xIndices[i] = idx;
436:             }
437: 
438:             // bStar = Σ_XX^{-1} Σ_XY (Maathuis et al. 2009, eq. 4)
439:             Matrix rX = this.allCovariances.getSelection(xIndices, xIndices);
440:             Matrix rY = this.allCovariances.getSelection(xIndices, new int[]{yIndex});
441: 
442:             Matrix bStar;
443:             try {
444:                 bStar = rX.inverse().times(rY);
445:             } catch (SingularMatrixException e) {
446:                 TetradLogger.getInstance().warn("Singularity encountered when regressing "
447:                         + LogUtilsSearch.getScoreFact(child, regressors));
448:                 return 0.0;
449:             }
450: 
451:             return bStar.get(parentIndexInRegressors, 0);
452: 
453:         } catch (SingularMatrixException e) {
454:             throw new RuntimeException("Singularity encountered when regressing "
455:                     + LogUtilsSearch.getScoreFact(child, regressors));
456:         }

189:      * Calculates the PCER (Per Comparison Error Rate) based on the given parameters. See Meinhausen and Buhlmann (2010).
190:      *
191:      * @param pi The stability (selection probability).
192:      * @param q  The expected number of false positives (top bracket size).
193:      * @param p  The total number of possible causes.
194:      * @return The calculated PCER bound.
195:      */
196:     private static double pcer(double pi, double q, double p) {
197:         if (pi <= 0.5) return 1.0;
198:         return (1.0 / ((2. * pi - 1.))) * ((q * q) / (p * p));
199:     }

