673:      * Returns a text table from the given records
674:      *
675:      * @param records a {@link java.util.LinkedList} object
676:      * @return a {@link java.lang.String} object
677:      */
678:     public String makeTable(LinkedList<Record> records) {
679:         if (records.isEmpty()) {
680:             throw new IllegalArgumentException("There were no CSTaR records generated. Perhaps the parameters are wrong.");
681:         }
682: 
683:         String header = "# Potential Causes = " + records.getFirst().getNumCauses() + "\n" + "# Potential Effects = " + records.getFirst().getNumEffects() + "\n" + "Top Bracket (âqâ) = " + this.topBracket + "\n\n";
684: 
685:         int numColumns = 6;
686: 
687:         TextTable table = new TextTable(records.size() + 1, numColumns);
688:         NumberFormat nf = new DecimalFormat("0.0000");
689:         int column = 0;
690: 
691:         table.setToken(0, column++, "Index");
692:         table.setToken(0, column++, "Cause");
693:         table.setToken(0, column++, "Effect");
694:         table.setToken(0, column++, "PI");
695:         table.setToken(0, column++, "Effect");
696: 
697:         table.setToken(0, column, "PCER");
698: 
699:         if (records.isEmpty()) {
700:             return "\nThere are no records above chance.\n";
701:         }
702: 
703:         int p = records.getLast().getNumCauses();
704: 
705:         for (int i = 0; i < records.size(); i++) {
706:             Node cause = records.get(i).getCauseNode();
707:             Node effect = records.get(i).getEffectNode();
708:             column = 0;
709: 
710:             table.setToken(i + 1, column++, String.valueOf(i + 1));
711:             table.setToken(i + 1, column++, cause.getName());
712:             table.setToken(i + 1, column++, effect.getName());
713:             table.setToken(i + 1, column++, nf.format(records.get(i).getPi()));
714:             table.setToken(i + 1, column++, nf.format(records.get(i).getMinBeta()));
715: 
716:             double pcer = Cstar.pcer(records.get(i).getPi(), (i + 1), p);
717:             table.setToken(i + 1, column, records.get(i).getPi() <= 0.5 ? "*" : nf.format(pcer));
718:         }
719: 
720:         return header + table;
721:     }
